INSERT INTO courses (id, title, subtitle, description, category, level, price_cents, currency, cover_image, instructor_id, instructor_name, published, modules_count, total_lessons, prerequisites, technologies, modules, created_at, updated_at) VALUES
  ('excel-basico-05', 'Excel Básico: La Pantalla, Datos, Fórmulas y Funciones Esenciales', 'Domina la interfaz de Excel, tipos de datos, formato desde Inicio, fórmulas con operadores (+, -, *, /, ^), referencias relativas/absolutas y funciones.', 'Curso práctico paso a paso diseñado para dominar la pantalla de Excel, la cuadrícula bidimensional, tipos de datos y edición, formato desde la pestaña Inicio, fórmulas con operadores y referencias relativas y absolutas con F4, cálculo del ITBIS del 18% y las 13 funciones matemáticas y estadísticas fundamentales.', 'Productividad', 'beginner', NULL, 'DOP', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, '["Excel","La Pantalla de Excel","Formato","Fórmulas","F4 / ITBIS","SI()","Simulador 3D"]'::jsonb, '[{"id":"mod-excel-0","title":"MÓDULO 0 — FUNDAMENTOS PREVIOS","durationMinutes":120,"quizQuestion":"¿Cómo se identifica una celda en Excel y qué símbolo fija las coordenadas al arrastrar?","quizOptions":["Con la letra de columna y el número de fila (ej. B3); el signo $ fija la coordenada","Con el número de fila y luego la letra (ej. 3B)","Únicamente con el número de fila"],"quizCorrectIndex":0,"quizEnabled":true,"questions":[{"id":"q-m0-1","prompt":"¿Cómo se identifica una celda en Excel y qué símbolo fija las coordenadas al arrastrar una fórmula?","explanation":"Las celdas se nombran primero por la letra de columna y luego el número de fila (ej. B3), y el signo $ bloquea fila y/o columna ($B$3).","multiple":false,"options":[{"id":"q-m0-1-a","text":"Con la letra de columna y el número de fila (ej. B3); el signo $ fija la coordenada"},{"id":"q-m0-1-b","text":"Con el número de fila y luego la letra (ej. 3B); el símbolo # fija la coordenada"},{"id":"q-m0-1-c","text":"Únicamente con el número de fila y comillas dobles"},{"id":"q-m0-1-d","text":"Mediante dos puntos (:) antes del nombre de columna"}],"correctIndexes":[0]},{"id":"q-m0-2","prompt":"Verdadero o Falso: Toda fórmula o función en Excel debe comenzar obligatoriamente con el signo igual (=) para que Excel la calcule en lugar de tratarla como texto.","explanation":"Verdadero. Sin el signo igual (=) inicial, Excel interpreta lo escrito como una cadena de texto literal.","multiple":false,"options":[{"id":"q-m0-2-v","text":"Verdadero"},{"id":"q-m0-2-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m0-3","prompt":"¿Qué combinación de hoja y celda referencia correctamente la celda B5 de una pestaña llamada \"Ventas 2026\" (con espacio en el nombre)?","explanation":"Cuando el nombre de la hoja contiene espacios, Excel exige encerrarlo entre comillas simples (''...'') antes del signo de exclamación (!).","multiple":false,"options":[{"id":"q-m0-3-a","text":"=Ventas 2026!B5"},{"id":"q-m0-3-b","text":"=''Ventas 2026''!B5"},{"id":"q-m0-3-c","text":"=[Ventas 2026]:B5"},{"id":"q-m0-3-d","text":"=\"Ventas 2026\"!B5"}],"correctIndexes":[1]},{"id":"q-m0-4","prompt":"Selecciona TODAS las afirmaciones correctas sobre el ciclo de la tecla F4 al editar una referencia como A1:","explanation":"Al pulsar F4 repetidamente, Excel rota entre referencia absoluta ($A$1), mixta con fila fija (A$1), mixta con columna fija ($A1) y relativa (A1).","multiple":true,"options":[{"id":"q-m0-4-a","text":"$A$1 bloquea tanto la columna A como la fila 1 al copiar la fórmula"},{"id":"q-m0-4-b","text":"A$1 deja libre la columna A y fija únicamente la fila 1"},{"id":"q-m0-4-c","text":"$A1 deja libre la fila 1 y fija únicamente la columna A"},{"id":"q-m0-4-d","text":"F4 elimina automáticamente la fórmula y deja solo el número resultante"}],"correctIndexes":[0,1,2]},{"id":"q-m0-5","prompt":"Verdadero o Falso: En la sintaxis de Excel (=FUNCION(arg1; [arg2])), los argumentos encerrados entre corchetes [ ] son siempre obligatorios.","explanation":"Falso. En la ayuda y barra flotante de Excel, los corchetes [ ] indican argumentos opcionales, mientras que los que no llevan corchetes son obligatorios.","multiple":false,"options":[{"id":"q-m0-5-v","text":"Verdadero"},{"id":"q-m0-5-f","text":"Falso"}],"correctIndexes":[1]},{"id":"q-m0-6","prompt":"Según la jerarquía matemática de Excel, ¿qué resultado devuelve la fórmula =2+3*4^2?","explanation":"Primero se calcula la potencia 4^2 = 16, luego la multiplicación 3*16 = 48 y por último la suma 2+48 = 50.","multiple":false,"options":[{"id":"q-m0-6-a","text":"50"},{"id":"q-m0-6-b","text":"400"},{"id":"q-m0-6-c","text":"80"},{"id":"q-m0-6-d","text":"20"}],"correctIndexes":[0]},{"id":"q-m0-7","prompt":"¿Qué error aparece en una celda cuando intentas dividir un número entre 0 o entre una celda vacía?","explanation":"#¡DIV/0! indica que el divisor es cero o una celda sin valor numérico.","multiple":false,"options":[{"id":"q-m0-7-a","text":"#¡VALOR!"},{"id":"q-m0-7-b","text":"#¡DIV/0!"},{"id":"q-m0-7-c","text":"#REF!"},{"id":"q-m0-7-d","text":"#¿NOMBRE?"}],"correctIndexes":[1]},{"id":"q-m0-8","prompt":"Verdadero o Falso: Al escribir =PRO en una celda y presionar la tecla Tab (Tabulador), Excel autocompleta el nombre de la función sugerida y abre su paréntesis.","explanation":"Verdadero. La tecla Tab acepta la función seleccionada en la lista desplegable y abre automáticamente el paréntesis de inicio.","multiple":false,"options":[{"id":"q-m0-8-v","text":"Verdadero"},{"id":"q-m0-8-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m0-9","prompt":"¿En qué orden evalúa Excel una fórmula con funciones anidadas como =REDONDEAR(PROMEDIO(B2:B20); 2)?","explanation":"Siempre se resuelve primero la función más interna (PROMEDIO) y su valor resultante se pasa como argumento a la función externa (REDONDEAR).","multiple":false,"options":[{"id":"q-m0-9-a","text":"Primero calcula PROMEDIO(B2:B20) y luego aplica REDONDEAR sobre ese resultado"},{"id":"q-m0-9-b","text":"Primero aplica REDONDEAR a B2 y después calcula PROMEDIO hasta B20"},{"id":"q-m0-9-c","text":"Ejecuta ambas en paralelo devolviendo dos celdas distintas"}],"correctIndexes":[0]},{"id":"q-m0-10","prompt":"Verdadero o Falso: El operador de concatenación & sirve para unir textos y valores en una sola cadena, por ejemplo =\"Total: \"&100.","explanation":"Verdadero. El operador ampersand (&) concatena cadenas de texto o combina texto con valores de celdas.","multiple":false,"options":[{"id":"q-m0-10-v","text":"Verdadero"},{"id":"q-m0-10-f","text":"Falso"}],"correctIndexes":[0]}],"lessons":[{"id":"les-excel-0-0","title":"0.0 Conceptos Básicos: Columnas, Filas y Celdas","durationMinutes":15,"summary":"La cuadrícula bidimensional de Excel: columnas con letras (A-XFD), filas con números (1-1048576) y celdas únicas (ej. B3).","content":"La hoja de cálculo organiza toda la información en una cuadrícula bidimensional de columnas (verticales, identificadas con letras de la A a la XFD) y filas (horizontales, identificadas con números del 1 al 1.048.576).\n\n• Columnas: Verticales con letras (A, B, C...). Hay 16.384 columnas hasta XFD.\n• Filas: Horizontales con números (1, 2, 3...). Hay 1.048.576 filas.\n• Celda: El cuadro donde cruzan una columna y una fila. Se nombra por su coordenada: primero la letra y luego el número (ej. B3 o C4).\n• Cuadro de nombres: Muestra en todo momento la celda activa que tienes seleccionada.\n• Barra de fórmulas: Muestra y permite editar el contenido real de la celda activa.\n\nExplora la guía interactiva completa adjunta en los materiales de esta lección para ver la cuadrícula y practicar con la pantalla interactiva.","materials":[{"id":"mat-partes-pantalla-img","name":"Partes principales de una hoja de cálculo de Excel","url":"/assets/aistudio/Infograf_a__Partes_principales_de_la_hoja_de_Excel_8da439cd.webp","type":"image","description":"Vista panorámica de la interfaz: Cinta de opciones, Cuadro de nombres (celda B7), Barra de fórmulas (=SUMA(B2:B6)), Columnas (A–K), Filas numeradas, Celda activa, pestañas de Hojas y Barra de zoom.","sizeByte":107702,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-concepto-columnas-00","name":"Columnas en Excel: Eje Vertical (A–XFD)","url":"/assets/images/excel_concepto_columnas_1795446880239.jpg","type":"image","description":"Eje vertical de la hoja de cálculo: 16.384 columnas nombradas con letras (A, B, C... hasta XFD). Hacer clic en la letra de columna la selecciona de arriba hacia abajo.","sizeByte":437622,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-concepto-filas-00","name":"Filas en Excel: Eje Horizontal (1–1.048.576)","url":"/assets/images/excel_concepto_filas_1795446901853.jpg","type":"image","description":"Eje horizontal numerado del 1 al 1.048.576. Pulsar el número en el margen izquierdo selecciona toda la fila completa a lo ancho de la hoja.","sizeByte":469026,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-concepto-celda-00","name":"Celda Activa, Coordenadas y Cuadro de Nombres (C4)","url":"/assets/images/excel_concepto_celda_activa_1795446902202.jpg","type":"image","description":"Intersección única entre columna y fila (ej. Columna C + Fila 4 = Celda C4), reflejada en el Cuadro de nombres junto al contenido real en la Barra de fórmulas y el controlador de relleno.","sizeByte":510611,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-concepto-rangos-00","name":"Rangos de Celdas Continuos (B2:D5)","url":"/assets/images/excel_concepto_rangos_1795446902863.jpg","type":"image","description":"Bloque rectangular definido por celda inicial y celda final unidas con dos puntos (:). El ejemplo B2:D5 abarca exactamente 12 celdas contiguas.","sizeByte":440221,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-cuadricula-basica-00","name":"Cuadrícula bidimensional: Columnas, Filas, Celda B3 y Rango D2:E4","url":"/assets/images/excel_columnas_filas_celdas_1795446159490.jpg","type":"image","description":"Síntesis visual de coordenadas: columnas verticales, filas horizontales, celda activa B3 y rango continuo D2:E4 en un mismo plano.","sizeByte":333205,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-estructura-grid-00","name":"Estructura completa de la cuadrícula: Columnas, Filas y Celda B3","url":"/assets/images/excel_estructura_grid_completa_1795447779102.jpg","type":"image","description":"Infografía unificada de conceptos básicos: encabezados alfabéticos de columna, encabezados numéricos de fila, barra de fórmulas y celda activa B3 en intersección.","sizeByte":453911,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-00","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-0-1","title":"0.1 Anatomía de una función (nombre, argumentos, sintaxis)","durationMinutes":15,"summary":"Estructura universal de toda fórmula en Excel: signo igual, nombre de función, paréntesis y separadores.","content":"Toda función inicia con = seguido del nombre (por ejemplo SUMA), paréntesis de apertura y sus argumentos separados por coma o punto y coma según la configuración regional. Ejemplo: =SUMA(A1:A10). Comprender los argumentos obligatorios frente a los opcionales [entre corchetes] te permite leer cualquier función sin memorizarla.\n\nPartes de una función:\n1. Signo igual (=): Le indica a Excel que ejecute un cálculo y no almacene texto plano.\n2. Nombre oficial de la función (ej. SUMA, PROMEDIO, SI).\n3. Paréntesis de apertura (:\n4. Argumentos separados por comas o punto y coma.\n5. Paréntesis de cierre ).","materials":[{"id":"mat-img-anatomia-funcion-01","name":"Anatomía universal de una función en Excel (=SUMA)","url":"/assets/images/excel_anatomia_funcion_1795445064862.jpg","type":"image","description":"Desglose sintáctico de toda función: signo igual (=) inicial para activar el cálculo, nombre oficial en mayúsculas, paréntesis delimitadores y argumentos separados por punto y coma (;).","sizeByte":465650,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-01","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-0-2","title":"0.2 Referencias: relativas, absolutas ($A$1) y mixtas","durationMinutes":15,"summary":"Controla cómo cambian o permanecen fijas las celdas al copiar fórmulas con F4.","content":"Una referencia relativa (A1) se ajusta al arrastrar la fórmula. Una referencia absoluta ($A$1) bloquea fila y columna, ideal para tasas de impuestos o tipos de cambio. Las referencias mixtas ($A1 o A$1) fijan solo la columna o solo la fila para construir tablas de doble entrada en segundos.\n\nCiclo F4:\n• A1: Relativa (cambia al copiar)\n• $A$1: Absoluta (nunca cambia)\n• A$1: Mixta (fila fija, columna libre)\n• $A1: Mixta (columna fija, fila libre)","materials":[{"id":"mat-img-referencias-f4-02","name":"Referencias Relativas, Absolutas ($A$1) y Mixtas (F4)","url":"/assets/images/excel_referencias_f4_1795445064452.jpg","type":"image","description":"Comparación del desplazamiento de coordenadas al copiar fórmulas hacia abajo o derecha y uso de la tecla F4 para alternar entre A1, $A$1, A$1 y $A1.","sizeByte":429923,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-02","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-0-3","title":"0.3 Referencias a hojas y libros externos","durationMinutes":15,"summary":"Conecta datos entre pestañas usando el operador ! y vincula otros archivos de Excel.","content":"Para referenciar una celda en otra hoja usa el formato NombreHoja!Celda (o ''Nombre con espacios''!A1). Para libros externos abiertos o guardados, Excel antepone el nombre del archivo entre corchetes: =[Presupuesto.xlsx]Resumen!$B$4.\n\n• Misma hoja: =A1+B1\n• Otra hoja del mismo libro: =Hoja2!A1\n• Hoja con espacios: =''Ventas 2026''!B5\n• Libro externo: =''[Presupuesto.xlsx]Hoja1''!A1","materials":[{"id":"mat-img-referencias-hojas-03","name":"Referencias entre hojas y libros externos (! y [Libro.xlsx])","url":"/assets/images/excel_referencias_hojas_externas_1795447779076.jpg","type":"image","description":"Sintaxis visual para enlazar datos de otras pestañas (=Hoja2!A1, =''Ventas 2026''!B5) y archivos externos (=[Presupuesto.xlsx]Resumen!$B$4).","sizeByte":311888,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-03-referencias-animado-html","name":"Tutorial Animado 2D: Referencias a hojas y libros externos (HTML)","url":"/excel-basico/0.3 Referencias a hojas y libros externos.html","type":"doc","sizeByte":76516,"uploadedAt":"2026-11-22T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-03","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-0-4","title":"0.4 Operadores (aritméticos, comparación, concatenación, referencia)","durationMinutes":15,"summary":"Jerarquía de cálculo: +, -, *, /, ^, =, <>, &, : y espacio de intersección.","content":"Excel evalúa primero paréntesis y exponentes (^), luego multiplicación/división (*, /) y finalmente suma/resta (+, -). Los operadores de comparación (=, >, <, >=, <=, <>) devuelven VERDADERO o FALSO. El operador & concatena textos y : define rangos continuos (A1:C10).\n\n• Aritméticos: + - * / ^ %\n• Comparación: = > < >= <= <>\n• Concatenación: & (une texto)\n• Referencia: : (rango), , o ; (unión), espacio (intersección)","materials":[{"id":"mat-img-jerarquia-operadores-04","name":"Jerarquía de evaluación de operadores en fórmulas de Excel","url":"/assets/images/excel_jerarquia_formulas_1795446160425.jpg","type":"image","description":"Prioridad de ejecución: 1) Paréntesis (), 2) Potencia ^ y porcentaje %, 3) Multiplicación * y división /, 4) Suma + y resta -. Muestra la diferencia entre =(2+3)*4 = 20 y =2+3*4 = 14.","sizeByte":426537,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-tipos-operadores-04","name":"Tipos de operadores en Excel: aritméticos, comparación y texto (&)","url":"/assets/images/excel_tipos_operadores_1795447919466.jpg","type":"image","description":"Resumen visual de los cuatro niveles de precedencia aritmética junto al operador de concatenación (&) y operadores lógicos de comparación (=, >, <, <>).","sizeByte":459683,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-04-operadores-animado-html","name":"Tutorial Animado 2D: Operadores en Excel (HTML)","url":"/excel-basico/0.4 Operadores (aritméticos, comparación, concatenación, referencia.html","type":"doc","sizeByte":76516,"uploadedAt":"2026-11-22T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-04","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-0-5","title":"0.5 Uso del Asistente de funciones y autocompletado","durationMinutes":15,"summary":"Aprovecha Tab, fx y las sugerencias en pantalla para escribir fórmulas sin errores tipográficos.","content":"Al escribir =PRO, Excel despliega las coincidencias; pulsa Tabulador para completar y abrir el paréntesis. El botón fx (Insertar función) muestra la descripción de cada argumento y el resultado preliminar en vivo antes de confirmar.","materials":[{"id":"mat-img-asistente-autocompletado-05","name":"Asistente de funciones (fx), autocompletado y tecla Tab","url":"/assets/images/excel_asistente_autocompletado_1795447781173.jpg","type":"image","description":"Cómo aprovechar el menú emergente al escribir =PRO, pulsar Tab para autocompletar, distinguir argumentos obligatorios de [opcionales] y abrir el cuadro fx.","sizeByte":480070,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-05","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-0-6","title":"0.6 Cómo leer y corregir errores (#¡VALOR!, #N/A, #REF!, #DIV/0!)","durationMinutes":15,"summary":"Diagnóstico rápido de los errores más frecuentes en hojas de cálculo profesionales.","content":"#DIV/0! ocurre al dividir entre cero o celda vacía; #¡VALOR! indica tipo de dato incompatible (sumar texto); #REF! aparece cuando se eliminó una celda referenciada; #N/A señala que una búsqueda no halló coincidencia. Combina la auditoría de fórmulas con SI.ERROR cuando corresponda.","materials":[{"id":"mat-img-errores-comunes-06","name":"Guía visual de errores frecuentes en Excel (#¡DIV/0!, #¿NOMBRE?, #¡VALOR!, #REF!)","url":"/assets/images/excel_errores_comunes_1795445065276.jpg","type":"image","description":"Tabla de diagnóstico para identificar por código la causa exacta del error en una fórmula (división por cero, texto en operación numérica, referencia eliminada o nombre mal escrito) y cómo corregirlo.","sizeByte":667178,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-06","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-0-7","title":"0.7 Anidar funciones correctamente","durationMinutes":15,"summary":"Usa el resultado de una función como argumento directo de otra de forma legible.","content":"Anidar consiste en colocar una función dentro de un argumento de otra, por ejemplo: =REDONDEAR(PROMEDIO(B2:B20); 2). Cuida que cada paréntesis de apertura tenga su cierre del mismo color y valida primero la función interna antes de envolverla.","materials":[{"id":"mat-img-anidar-funciones-07","name":"Anidación de funciones: evaluación de adentro hacia afuera","url":"/assets/images/excel_anidar_funciones_1795447781695.jpg","type":"image","description":"Ejemplo paso a paso de =REDONDEAR(PROMEDIO(B2:B20); 2): primero se resuelve la función interna PROMEDIO y su resultado alimenta a la función externa REDONDEAR.","sizeByte":424406,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-fundamentos-previos-html-07","name":"Guía Interactiva: Fundamentos Previos y Pantalla de Excel (HTML)","url":"/excel-basico/FUNDAMENTOSPREVIOS.html","type":"doc","sizeByte":111419,"uploadedAt":"2026-11-22T00:00:00.000Z"}]}]},{"id":"mod-excel-1","title":"MÓDULO 1: LA PANTALLA DE EXCEL","durationMinutes":45,"quizQuestion":"¿Qué componente de la pantalla de Excel muestra la coordenada exacta de la celda activa seleccionada?","quizOptions":["El Cuadro de nombres","La Barra de estado","La Cinta de opciones"],"quizCorrectIndex":0,"quizEnabled":true,"questions":[{"id":"q-m1-1","prompt":"¿Qué componente de la pantalla de Excel muestra la coordenada exacta de la celda activa seleccionada (ej. B7)?","explanation":"El Cuadro de nombres está ubicado a la izquierda de la Barra de fórmulas y muestra siempre la referencia de la celda activa o rango seleccionado.","multiple":false,"options":[{"id":"q-m1-1-a","text":"El Cuadro de nombres"},{"id":"q-m1-1-b","text":"La Barra de estado"},{"id":"q-m1-1-c","text":"La Cinta de opciones"},{"id":"q-m1-1-d","text":"La Barra de zoom"}],"correctIndexes":[0]},{"id":"q-m1-2","prompt":"Verdadero o Falso: Un \"Libro\" de Excel (.xlsx) es el archivo completo y puede contener múltiples \"Hojas\" en pestañas inferiores.","explanation":"Verdadero. Un libro es el contenedor (.xlsx) y cada pestaña en la parte inferior es una hoja de cálculo independiente dentro del archivo.","multiple":false,"options":[{"id":"q-m1-2-v","text":"Verdadero"},{"id":"q-m1-2-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m1-3","prompt":"¿Qué muestra la Barra de fórmulas cuando seleccionas una celda que contiene una operación calculada?","explanation":"Mientras la celda muestra el resultado final en la cuadrícula, la Barra de fórmulas exhibe y permite editar la fórmula subyacente (ej. =SUMA(B2:B6)).","multiple":false,"options":[{"id":"q-m1-3-a","text":"Solo el nombre de la fuente y tamaño aplicado"},{"id":"q-m1-3-b","text":"El contenido real o fórmula escrita dentro de la celda activa"},{"id":"q-m1-3-c","text":"El promedio de todas las hojas del libro"},{"id":"q-m1-3-d","text":"La fecha de última modificación del archivo"}],"correctIndexes":[1]},{"id":"q-m1-4","prompt":"Selecciona TODAS las teclas o acciones válidas para moverte entre celdas en la cuadrícula de Excel:","explanation":"Puedes navegar con las flechas direccionales, pulsar Tab para avanzar a la derecha, Enter para bajar o hacer clic directamente en cualquier celda.","multiple":true,"options":[{"id":"q-m1-4-a","text":"Pulsar Tab para desplazarse una celda hacia la derecha"},{"id":"q-m1-4-b","text":"Pulsar Enter para desplazarse hacia la celda inferior"},{"id":"q-m1-4-c","text":"Usar las flechas direccionales del teclado"},{"id":"q-m1-4-d","text":"Pulsar Esc para saltar a la última fila del libro"}],"correctIndexes":[0,1,2]},{"id":"q-m1-5","prompt":"Verdadero o Falso: Hacer clic directamente sobre la letra del encabezado de una columna selecciona la fila horizontal completa.","explanation":"Falso. Hacer clic sobre la letra superior selecciona toda la columna vertical; para seleccionar una fila horizontal se hace clic sobre el número en el margen izquierdo.","multiple":false,"options":[{"id":"q-m1-5-v","text":"Verdadero"},{"id":"q-m1-5-f","text":"Falso"}],"correctIndexes":[1]},{"id":"q-m1-6","prompt":"¿Cuántas celdas abarca exactamente el rango rectangular A1:D4?","explanation":"De la columna A a la D hay 4 columnas y de la fila 1 a la 4 hay 4 filas: 4 × 4 = 16 celdas.","multiple":false,"options":[{"id":"q-m1-6-a","text":"8 celdas"},{"id":"q-m1-6-b","text":"12 celdas"},{"id":"q-m1-6-c","text":"16 celdas"},{"id":"q-m1-6-d","text":"4 celdas"}],"correctIndexes":[2]},{"id":"q-m1-7","prompt":"¿Cómo se cambia rápidamente el nombre de una pestaña de hoja (por ejemplo de \"Hoja1\" a \"Práctica\")?","explanation":"Haciendo doble clic directamente sobre el nombre de la pestaña en la barra inferior y escribiendo el nuevo nombre seguido de Enter.","multiple":false,"options":[{"id":"q-m1-7-a","text":"Doble clic sobre el nombre de la pestaña inferior y presionar Enter"},{"id":"q-m1-7-b","text":"Escribir el nuevo nombre dentro de la celda A1"},{"id":"q-m1-7-c","text":"Pulsando la barra de zoom en la esquina inferior derecha"}],"correctIndexes":[0]},{"id":"q-m1-8","prompt":"Verdadero o Falso: El botón con el símbolo + situado junto a las pestañas inferiores agrega una nueva hoja en blanco al libro actual.","explanation":"Verdadero. El ícono (+) crea inmediatamente una nueva hoja de cálculo dentro del mismo libro.","multiple":false,"options":[{"id":"q-m1-8-v","text":"Verdadero"},{"id":"q-m1-8-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m1-9","prompt":"¿Qué atajo de teclado abre el cuadro \"Ir a\" para saltar instantáneamente a una celda lejana como Z500?","explanation":"La tecla F5 (o Ctrl + I) abre el cuadro \"Ir a\", donde puedes escribir cualquier referencia exacta para navegar de inmediato.","multiple":false,"options":[{"id":"q-m1-9-a","text":"Tecla F5"},{"id":"q-m1-9-b","text":"Tecla F2"},{"id":"q-m1-9-c","text":"Tecla Esc"},{"id":"q-m1-9-d","text":"Tecla Supr"}],"correctIndexes":[0]},{"id":"q-m1-10","prompt":"Verdadero o Falso: La Cinta de opciones agrupa las herramientas de Excel en pestañas temáticas como Inicio, Insertar, Fórmulas y Datos.","explanation":"Verdadero. Toda la barra superior se organiza por pestañas y grupos lógicos dentro de la Cinta de opciones.","multiple":false,"options":[{"id":"q-m1-10-v","text":"Verdadero"},{"id":"q-m1-10-f","text":"Falso"}],"correctIndexes":[0]}],"lessons":[{"id":"les-excel-1-1","title":"1.1 Las piezas de la pantalla de Excel","durationMinutes":15,"summary":"Excel es una cuadrícula gigante donde guardas datos y haces cálculos; al abrirlo verás siempre las mismas piezas: Libro, Hoja, Celda, Columnas y filas, Cuadro de nombres, Barra de fórmulas y Cinta de opciones.","content":"Excel es una cuadrícula gigante donde guardas datos y haces cálculos; al abrirlo verás siempre las mismas piezas fundamentales:\n\n• Libro: El archivo completo de Excel (.xlsx).\n• Hoja: Cada pestaña dentro del libro, abajo a la izquierda. Un libro nuevo empieza con una.\n• Celda: El cuadro donde cruzan una columna y una fila. Se nombra por su ubicación, por ejemplo B3.\n• Columnas y filas: Las columnas se nombran con letras (A, B, C…) y las filas con números (1, 2, 3…).\n• Cuadro de nombres: A la izquierda de la barra de fórmulas: muestra qué celda tienes seleccionada.\n• Barra de fórmulas: Muestra y te deja editar el contenido real de la celda activa.\n• Cinta de opciones: Las pestañas de arriba (Inicio, Insertar, Fórmulas, Datos, Vista…) con todos los comandos.\n\nUsa el simulador interactivo disponible en esta lección para explorar cada una de las 9 piezas clave y familiarizarte con el entorno real de Microsoft Excel.","materials":[{"id":"mat-img-pantalla-excel-11","name":"Partes principales de una hoja de cálculo de Excel","url":"/assets/aistudio/Infograf_a__Partes_principales_de_la_hoja_de_Excel_8da439cd.webp","type":"image","description":"Mapa de navegación de la ventana de Excel: ubicación de la Cinta de opciones, Cuadro de nombres, Barra de fórmulas, Celda activa y pestañas de hojas del libro.","sizeByte":107702,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-cuadricula-excel-11","name":"Sistema de coordenadas: Columnas, Filas, Celda B3 y Rango D2:E4","url":"/assets/images/excel_columnas_filas_celdas_1795446159490.jpg","type":"image","description":"Referencia espacial dentro de la cuadrícula de Excel para distinguir encabezados de columna, números de fila, celda activa individual y selección rectangular de rango.","sizeByte":333205,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-1-2","title":"1.2 Cómo moverte y seleccionar rangos","durationMinutes":15,"summary":"Técnicas esenciales para navegar en la cuadrícula con el ratón y el teclado: clics, flechas, Tab, Enter y selección de rangos completos.","content":"Para moverte con velocidad y seguridad en la cuadrícula de Excel sigue estas reglas:\n\n• Haz clic en una celda para seleccionarla de inmediato.\n• Usa las flechas del teclado, o Tab (avanza hacia la derecha) y Enter (avanza hacia abajo).\n• Arrastra con el ratón para seleccionar un rango continuo de celdas, por ejemplo A1:C5.\n• Haz clic en la letra de una columna o en el número de una fila para seleccionarla completa de extremo a extremo.","materials":[{"id":"mat-img-concepto-rangos-12","name":"Selección de rangos continuos con dos puntos (B2:D5)","url":"/assets/images/excel_concepto_rangos_1795446902863.jpg","type":"image","description":"Define un rango continuo arrastrando desde la celda inicial superior izquierda (B2) hasta la esquina opuesta inferior derecha (D5).","sizeByte":440221,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-rangos-seleccion-12","name":"Visualización de celda única (B3) vs rango continuo (D2:E4)","url":"/assets/images/excel_columnas_filas_celdas_1795446159490.jpg","type":"image","description":"Identifica la diferencia entre seleccionar una celda puntual (B3) y arrastrar desde la esquina superior izquierda (D2) hasta la inferior derecha (E4) para formar el rango D2:E4.","sizeByte":333205,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-1-3","title":"1.3 Ejercicio 1: Navegación, nombramiento de hoja y rangos","durationMinutes":15,"summary":"Práctica paso a paso: abrir libro en blanco, escribir nombre en A1, seleccionar A1:D4, renombrar la pestaña a «Práctica» y añadir una segunda hoja con +.","content":"Paso a paso del Ejercicio 1:\n\n1. Abre un libro en blanco en Excel.\n2. Escribe tu nombre en la celda A1 y presiona Enter.\n3. Selecciona el rango A1:D4 arrastrando el ratón y fíjate cómo lo muestra el Cuadro de nombres.\n4. Haz doble clic en el nombre de la pestaña, cámbialo por «Práctica» y presiona Enter.\n5. Pulsa el signo + junto a la pestaña para añadir una segunda hoja de cálculo.","materials":[{"id":"mat-img-navegacion-hojas-13","name":"Navegación rápida en libros: hojas, saltos con Ctrl, F5 y selección","url":"/assets/images/excel_navegacion_hojas_1795447920960.jpg","type":"image","description":"Atajos visuales para desplazarte entre pestañas (Ctrl+AvPág), saltar al borde de datos (Ctrl+Flechas), ir directo a una celda con F5 o seleccionar tablas completas (Ctrl+E).","sizeByte":372279,"uploadedAt":"2026-11-23T00:00:00.000Z"}]}]},{"id":"mod-excel-2","title":"MÓDULO 2: DATOS Y FORMATO","durationMinutes":60,"quizQuestion":"¿Hacia qué lado de la celda se alinean automáticamente los números en Excel?","quizOptions":["A la derecha","A la izquierda","Al centro"],"quizCorrectIndex":0,"quizEnabled":true,"questions":[{"id":"q-m2-1","prompt":"¿Hacia qué lado de la celda se alinean automáticamente los números en Excel cuando no tienen alineación manual aplicada?","explanation":"Por defecto en Excel, los números y fechas válidas se alinean a la derecha, mientras que las cadenas de texto se alinean a la izquierda.","multiple":false,"options":[{"id":"q-m2-1-a","text":"A la derecha"},{"id":"q-m2-1-b","text":"A la izquierda"},{"id":"q-m2-1-c","text":"Al centro"},{"id":"q-m2-1-d","text":"Justificado automáticamente"}],"correctIndexes":[0]},{"id":"q-m2-2","prompt":"Verdadero o Falso: Presionar la tecla F2 sobre una celda seleccionada permite editar su contenido actual sin borrar lo que ya estaba escrito.","explanation":"Verdadero. F2 (al igual que hacer doble clic en la celda) activa el cursor de edición conservando el texto o fórmula existente.","multiple":false,"options":[{"id":"q-m2-2-v","text":"Verdadero"},{"id":"q-m2-2-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m2-3","prompt":"¿Qué ocurre si escribes \"Lunes\" en una celda y arrastras hacia abajo usando el controlador de relleno (cuadro verde en la esquina inferior derecha)?","explanation":"Excel reconoce \"Lunes\" como una serie cronológica y completa automáticamente Martes, Miércoles, Jueves, etc.","multiple":false,"options":[{"id":"q-m2-3-a","text":"Se borra el texto de todas las celdas arrastradas"},{"id":"q-m2-3-b","text":"Excel continúa la serie de días: Martes, Miércoles, Jueves..."},{"id":"q-m2-3-c","text":"Convierte la palabra Lunes en una fecha aleatoria"},{"id":"q-m2-3-d","text":"Se cambia el formato de la celda a Porcentaje"}],"correctIndexes":[1]},{"id":"q-m2-4","prompt":"Selecciona TODAS las herramientas que pertenecen al grupo \"Fuente\" o \"Alineación\" en la pestaña Inicio:","explanation":"Negrita/color/bordes pertenecen al grupo Fuente; Combinar y centrar y alineación horizontal pertenecen al grupo Alineación; Moneda ($) pertenece a Número.","multiple":true,"options":[{"id":"q-m2-4-a","text":"Negrita, cursiva, color de relleno y bordes de celda"},{"id":"q-m2-4-b","text":"Combinar y centrar títulos sobre varias columnas"},{"id":"q-m2-4-c","text":"Centrar contenido horizontal y verticalmente"},{"id":"q-m2-4-d","text":"Insertar gráficos dinámicos de barras 3D"}],"correctIndexes":[0,1,2]},{"id":"q-m2-5","prompt":"Verdadero o Falso: Al aplicar formato de Porcentaje (%) a una celda que contiene el número 0.15, Excel cambia el valor guardado internamente a 15.","explanation":"Falso. El formato solo modifica la apariencia visual (muestra 15%), pero el valor numérico interno almacenado continúa siendo 0.15 para los cálculos.","multiple":false,"options":[{"id":"q-m2-5-v","text":"Verdadero"},{"id":"q-m2-5-f","text":"Falso"}],"correctIndexes":[1]},{"id":"q-m2-6","prompt":"Si una celda almacena el valor numérico 18 y le aplicas directamente el formato Porcentaje (%), ¿qué mostrará Excel?","explanation":"El formato Porcentaje multiplica visualmente el valor por 100: 18 × 100 = 1800%. Para mostrar 18% debe almacenarse 0.18 (o escribir \"18%\" directamente).","multiple":false,"options":[{"id":"q-m2-6-a","text":"18%"},{"id":"q-m2-6-b","text":"0.18%"},{"id":"q-m2-6-c","text":"1800%"},{"id":"q-m2-6-d","text":"#¡VALOR!"}],"correctIndexes":[2]},{"id":"q-m2-7","prompt":"¿Cuál es la forma más rápida de ajustar automáticamente el ancho de una columna al contenido más largo que contiene?","explanation":"Hacer doble clic en el borde derecho entre las letras de encabezado (por ejemplo entre B y C) ejecuta el autoajuste inmediato.","multiple":false,"options":[{"id":"q-m2-7-a","text":"Hacer doble clic en el borde derecho de la letra del encabezado de columna"},{"id":"q-m2-7-b","text":"Presionar Esc dos veces seguidas"},{"id":"q-m2-7-c","text":"Aplicar negrita a toda la hoja"}],"correctIndexes":[0]},{"id":"q-m2-8","prompt":"Verdadero o Falso: Si escribes manualmente \"$65 pesos\" dentro de una celda de Precio, Excel podrá sumarlo y multiplicarlo normalmente en fórmulas aritméticas.","explanation":"Falso. Incluir palabras convierte la celda en texto y genera error #¡VALOR! al operar; debe escribirse 65 y aplicarse formato Moneda.","multiple":false,"options":[{"id":"q-m2-8-v","text":"Verdadero"},{"id":"q-m2-8-f","text":"Falso"}],"correctIndexes":[1]},{"id":"q-m2-9","prompt":"¿Qué tecla cancela lo que estás editando dentro de una celda y restaura el valor que tenía antes?","explanation":"La tecla Esc descarta cualquier cambio sin guardar y devuelve el contenido previo de la celda.","multiple":false,"options":[{"id":"q-m2-9-a","text":"Enter"},{"id":"q-m2-9-b","text":"Esc (Escape)"},{"id":"q-m2-9-c","text":"Tab"},{"id":"q-m2-9-d","text":"F4"}],"correctIndexes":[1]},{"id":"q-m2-10","prompt":"Verdadero o Falso: La tecla Supr (Delete) borra el contenido de las celdas seleccionadas sin eliminar las columnas ni desplazar las celdas vecinas.","explanation":"Verdadero. Supr limpia los datos o fórmulas de las celdas activas manteniendo intactos el formato y la estructura de la hoja.","multiple":false,"options":[{"id":"q-m2-10-v","text":"Verdadero"},{"id":"q-m2-10-f","text":"Falso"}],"correctIndexes":[0]}],"lessons":[{"id":"les-excel-2-1","title":"2.1 Escribir, editar datos y controlador de relleno","durationMinutes":15,"summary":"Una celda puede contener texto, números o fechas (texto a la izquierda, números a la derecha). Aprende a confirmar, cancelar con Esc, editar con F2 o Supr y autocompletar series con el controlador de relleno.","content":"Una celda puede contener texto, números o fechas, y Excel los trata distinto: el texto se alinea a la izquierda y los números a la derecha.\n\nEscribir y editar datos:\n• Escribe en la celda y presiona Enter para confirmar o Esc para cancelar.\n• Presiona F2 (o haz doble clic) para editar lo que ya está escrito dentro de la celda.\n• Presiona Supr (Delete) para borrar el contenido de las celdas seleccionadas.\n• Arrastra el cuadrito de la esquina inferior derecha de una celda (controlador de relleno) para repetir o continuar series: escribe Lunes y arrastra, y Excel completa automáticamente Martes, Miércoles, Jueves...","materials":[{"id":"mat-img-datos-relleno-21","name":"Alineación de tipos de datos, edición con F2 y controlador de relleno","url":"/assets/images/excel_datos_relleno_1795447885234.jpg","type":"image","description":"Diferencia visual entre texto alineado a la izquierda y números a la derecha, teclas F2/Enter/Esc y uso del controlador de relleno para completar series como días de la semana.","sizeByte":350039,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-2-2","title":"2.2 Formato desde la pestaña Inicio y formatos de número","durationMinutes":20,"summary":"Grupos Fuente, Alineación y Número. Formatos General, Número, Moneda, Porcentaje (0.15 → 15%), Fecha corta y autoajuste del ancho de columnas.","content":"Formato desde la pestaña Inicio:\n\n• Negrita, cursiva, subrayado: Grupo Fuente.\n• Cambiar tamaño o color de letra: Grupo Fuente.\n• Color de fondo y bordes: Grupo Fuente (icono de cubeta y cuadrícula).\n• Centrar o alinear: Grupo Alineación.\n• Combinar y centrar un título: Grupo Alineación.\n• Mostrar $, % o decimales: Grupo Número.\n• Ajustar el ancho de columna: Doble clic en el borde derecho de la letra de la columna.\n\nFormatos de número más usados: General, Número, Moneda, Porcentaje, Fecha corta y Fecha larga. Recuerda que el formato cambia cómo se ve el valor, no el valor guardado: 0.15 con formato Porcentaje se ve como 15 %.","materials":[{"id":"mat-img-formato-inicio-22","name":"Grupos de formato en Inicio: Fuente, Número ($, %) y Bordes","url":"/assets/images/excel_formato_inicio_1795447921508.jpg","type":"image","description":"Guía visual de formato en celdas: estilos de fuente y alineación, transformación visual de números (1500 → $1,500.00, 0.15 → 15%, 45 → 45.00) y diseño con rellenos y bordes.","sizeByte":439922,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-2-3","title":"2.3 Ejercicio 2: Lista de productos con formato profesional","durationMinutes":25,"summary":"Construye la lista de productos (Producto, Precio, Cantidad), aplica negrita, fondo, centrado, formato Moneda y autoajuste de columnas.","content":"Paso a paso del Ejercicio 2 (Lista de productos):\n\n1. En la hoja «Práctica», escribe en la fila 1 los encabezados: Producto, Precio, Cantidad.\n2. Debajo escribe cinco productos con su precio y cantidad (por ejemplo: Arroz a 65 y cantidad 10; Habichuelas a 75 y cantidad 8; Aceite a 120 y cantidad 5; Leche a 60 y cantidad 12; Azúcar a 45 y cantidad 15).\n3. Pon los encabezados en negrita, con fondo de color y texto centrado.\n4. Aplica formato Moneda a la columna Precio.\n5. Ajusta el ancho de las columnas haciendo doble clic en el borde derecho de cada letra.","materials":[{"id":"mat-img-tabla-productos-23","name":"Resultado modelo: Lista de productos con formato profesional y Moneda","url":"/assets/images/excel_tabla_productos_1795447786171.jpg","type":"image","description":"Ejemplo estructurado con encabezados destacados, formato Moneda en precios, alineación ordenada y ajuste automático de ancho de columnas.","sizeByte":478124,"uploadedAt":"2026-11-23T00:00:00.000Z"}]}]},{"id":"mod-excel-3","title":"MÓDULO 3: FÓRMULAS Y REFERENCIAS","durationMinutes":75,"quizQuestion":"¿Qué tipo de referencia fija la celda ($B$2) para que no cambie al arrastrar la fórmula hacia abajo o a la derecha?","quizOptions":["Referencia Absoluta ($B$2)","Referencia Relativa (B2)","Referencia Mixta ($B2)"],"quizCorrectIndex":0,"quizEnabled":true,"questions":[{"id":"q-m3-1","prompt":"¿Qué tipo de referencia fija tanto la columna como la fila ($B$2) para que no cambie al arrastrar la fórmula hacia abajo o a la derecha?","explanation":"Una referencia absoluta lleva doble signo dólar ($B$2) y permanece inamovible sin importar cuántas filas o columnas arrastres la fórmula.","multiple":false,"options":[{"id":"q-m3-1-a","text":"Referencia Absoluta ($B$2)"},{"id":"q-m3-1-b","text":"Referencia Relativa (B2)"},{"id":"q-m3-1-c","text":"Referencia Mixta ($B2)"},{"id":"q-m3-1-d","text":"Referencia Externa (B2!)"}],"correctIndexes":[0]},{"id":"q-m3-2","prompt":"Verdadero o Falso: Usar referencias (=B2*C2) en lugar de números fijos (=65*10) permite que los totales se recalculen solos si cambia el precio o la cantidad.","explanation":"Verdadero. Referenciar celdas hace que tu hoja de cálculo sea reactiva ante cualquier cambio en los datos base.","multiple":false,"options":[{"id":"q-m3-2-v","text":"Verdadero"},{"id":"q-m3-2-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m3-3","prompt":"En una factura donde la tasa del ITBIS (18%) está en la celda E1 y los subtotales en D2:D6, ¿qué fórmula debes escribir en E2 para luego arrastrar hacia E6?","explanation":"D2 debe avanzar relativamente a D3, D4... mientras que $E$1 debe quedar fija absolutamente en todas las filas.","multiple":false,"options":[{"id":"q-m3-3-a","text":"=D2*E1"},{"id":"q-m3-3-b","text":"=D2*$E$1"},{"id":"q-m3-3-c","text":"=$D$2*E1"},{"id":"q-m3-3-d","text":"=SUMA(D2;E1)"}],"correctIndexes":[1]},{"id":"q-m3-4","prompt":"Selecciona TODOS los operadores válidos junto con su significado correcto en Excel:","explanation":"* multiplica, / divide, ^ eleva a una potencia y <> evalúa si dos valores son distintos.","multiple":true,"options":[{"id":"q-m3-4-a","text":"* realiza multiplicación aritmética"},{"id":"q-m3-4-b","text":"^ eleva un número a una potencia (ej. =2^3 da 8)"},{"id":"q-m3-4-c","text":"<> compara si dos valores son distintos"},{"id":"q-m3-4-d","text":"x multiplica automáticamente celdas en Excel"}],"correctIndexes":[0,1,2]},{"id":"q-m3-5","prompt":"Verdadero o Falso: Si en una celda aparece ##### significa que la fórmula tiene un error matemático grave e irrecuperable.","explanation":"Falso. ##### únicamente indica que el ancho visual de la columna no alcanza para mostrar el número o fecha completa; basta ensanchar la columna.","multiple":false,"options":[{"id":"q-m3-5-v","text":"Verdadero"},{"id":"q-m3-5-f","text":"Falso"}],"correctIndexes":[1]},{"id":"q-m3-6","prompt":"¿Qué causa el error #¿NOMBRE? al escribir una fórmula en Excel?","explanation":"#¿NOMBRE? aparece cuando Excel no reconoce el nombre de la función (ej. escribir =PROMDIO en vez de =PROMEDIO) o falta comillas en un texto.","multiple":false,"options":[{"id":"q-m3-6-a","text":"Se escribió mal el nombre de una función o un rango inexistente"},{"id":"q-m3-6-b","text":"La columna es demasiado angosta"},{"id":"q-m3-6-c","text":"Se dividió entre cero"}],"correctIndexes":[0]},{"id":"q-m3-7","prompt":"¿Qué valor devuelve la comparación =15>=20 escrita en una celda de Excel?","explanation":"Los operadores de comparación devuelven un valor lógico booleano; como 15 no es mayor o igual a 20, el resultado es FALSO.","multiple":false,"options":[{"id":"q-m3-7-a","text":"VERDADERO"},{"id":"q-m3-7-b","text":"FALSO"},{"id":"q-m3-7-c","text":"-5"},{"id":"q-m3-7-d","text":"#¡VALOR!"}],"correctIndexes":[1]},{"id":"q-m3-8","prompt":"Verdadero o Falso: En Excel puedes usar un espacio en blanco entre dos rangos (ej. =SUMA(A1:C3 B2:D4)) como operador de intersección para tomar solo las celdas comunes.","explanation":"Verdadero. El operador de intersección en Excel es el espacio entre dos rangos y devuelve las celdas donde ambos coinciden.","multiple":false,"options":[{"id":"q-m3-8-v","text":"Verdadero"},{"id":"q-m3-8-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m3-9","prompt":"Si copias la fórmula =A2+$B$1 desde C2 hacia dos filas abajo (celda C4), ¿cómo quedará la fórmula en C4?","explanation":"La referencia relativa A2 avanza dos filas a A4, mientras que la referencia absoluta $B$1 permanece intacta.","multiple":false,"options":[{"id":"q-m3-9-a","text":"=A4+$B$3"},{"id":"q-m3-9-b","text":"=A2+$B$1"},{"id":"q-m3-9-c","text":"=A4+$B$1"},{"id":"q-m3-9-d","text":"=C4+$B$1"}],"correctIndexes":[2]},{"id":"q-m3-10","prompt":"Verdadero o Falso: Intentar sumar una celda con texto (\"Hola\") más un número (=A1+5) genera el error #¡VALOR!.","explanation":"Verdadero. Los operadores aritméticos (+, -, *, /) requieren operandos numéricos; operar texto incompatible arroja #¡VALOR!.","multiple":false,"options":[{"id":"q-m3-10-v","text":"Verdadero"},{"id":"q-m3-10-f","text":"Falso"}],"correctIndexes":[0]}],"lessons":[{"id":"les-excel-3-1","title":"3.1 Fórmulas, operadores básicos y jerarquía matemática","durationMinutes":20,"summary":"Una fórmula siempre empieza con (=). Operadores aritméticos (+, -, *, /, ^), jerarquía con paréntesis y ventajas de las referencias vs números fijos.","content":"Una fórmula siempre empieza con el signo igual (=) y le pide a Excel que calcule algo usando los valores de otras celdas.\n\nOperadores básicos:\n• Suma (+): Ejemplo =B2+C2\n• Resta (-): Ejemplo =B2-C2\n• Multiplicación (*): Ejemplo =B2*C2\n• División (/): Ejemplo =B2/C2\n• Potencia (^): Ejemplo =B2^2\n\nJerarquía matemática: Excel respeta el orden algebraico: primero paréntesis, luego potencias (^), después multiplicación y división (*, /), y al final suma y resta (+, -). Usa paréntesis para controlar el orden: =(A1+A2)*3.\n\nPor qué usar referencias y no números fijos: Si escribes =B2*C2 en lugar de =65*10, el resultado se actualiza solo cuando cambias el precio o la cantidad.","materials":[{"id":"mat-img-jerarquia-formulas-31","name":"Orden de evaluación matemática en fórmulas de Excel","url":"/assets/images/excel_jerarquia_formulas_1795446160425.jpg","type":"image","description":"Regla de precedencia paso a paso: primero paréntesis, luego potencias (^), después multiplicación/división y al final suma/resta. Evita resultados inesperados al agrupar con ().","sizeByte":426537,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-anatomia-formula-31","name":"Estructura de fórmula y argumentos en Excel","url":"/assets/images/excel_anatomia_funcion_1795445064862.jpg","type":"image","description":"Recordatorio visual de la sintaxis obligatoria con = inicial y referencias a rangos en lugar de valores fijos escritos manualmente.","sizeByte":465650,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-3-2","title":"3.2 Tipos de referencia (Relativa, Absoluta, Mixta), tecla F4 e ITBIS","durationMinutes":25,"summary":"Diferencias entre B2, $B$2 y $B2/B$2. Tecla F4 para alternar. Caso real: cálculo del ITBIS del 18% fijando la celda de tasa con =$E$1.","content":"Copiar fórmulas y tipos de referencia:\n\n• Relativa (B2): Se ajusta a la nueva posición al arrastrar (B2 pasa a B3 al copiar hacia abajo).\n• Absoluta ($B$2): No cambia nunca, congelando tanto la columna como la fila con el signo $.\n• Mixta ($B2 o B$2): Fija solo la columna ($B2) o solo la fila (B$2).\n\nPresiona F4 mientras editas una referencia para alternar entre estos tipos.\n\nEjemplo típico: calcular el ITBIS del 18% guardando la tasa en la celda E1 y usando =D2*$E$1 para que la tasa no se mueva al copiar la fórmula hacia las demás filas.","materials":[{"id":"mat-img-referencias-itbis-32","name":"Esquema práctico: Referencia absoluta ($E$1) para ITBIS 18% con F4","url":"/assets/images/excel_referencias_f4_1795445064452.jpg","type":"image","description":"Muestra por qué al fijar fila y columna con $ ($E$1) mediante F4, la tasa del 18% se mantiene anclada en todas las filas de la factura.","sizeByte":429923,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-img-itbis-factura-32","name":"Caso aplicado: Tabla de factura con Subtotal e ITBIS (18%) fijo","url":"/assets/images/excel_itbis_factura_1795447883578.jpg","type":"image","description":"Ejemplo numérico completo de factura: cálculo de Subtotal por línea (=B3*C3) multiplicado por la tasa fija en $F$1 (=D3*$F$1) sin desplazarse al arrastrar.","sizeByte":446648,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-3-3","title":"3.3 Diagnóstico de errores comunes (#¡DIV/0!, #¿NOMBRE?, #¡VALOR!, #####)","durationMinutes":15,"summary":"Significado y corrección de los errores más frecuentes en hojas de cálculo profesionales.","content":"Errores comunes en Excel y soluciones:\n\n• #¡DIV/0!: dividiste entre cero o entre una celda vacía. Corrige el divisor.\n• #¿NOMBRE?: escribiste mal el nombre de una función o referencia inexistente.\n• #¡VALOR!: intentaste operar matemáticamente con texto donde hacía falta un número.\n• #####: la columna es muy angosta; ensánchala haciendo doble clic en el borde derecho.","materials":[{"id":"mat-img-errores-comunes-33","name":"Tabla visual de diagnóstico: Errores comunes en Excel y su solución","url":"/assets/images/excel_errores_comunes_1795445065276.jpg","type":"image","description":"Referencia rápida de errores de cálculo y visualización en hoja de cálculo con su causa inmediata y corrección recomendada.","sizeByte":667178,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-3-4","title":"3.4 Ejercicio 3: Cálculo de Total e ITBIS reactivo","durationMinutes":15,"summary":"Práctica paso a paso: columna D con Total =B2*C2, arrastrar con controlador, celda E1 con 18%, cálculo de ITBIS =D2*$E$1 y verificación reactiva.","content":"Paso a paso del Ejercicio 3:\n\n1. En tu lista de productos de la hoja «Práctica», agrega la columna D con el título Total.\n2. En D2 escribe =B2*C2 y presiona Enter.\n3. Arrastra el controlador de relleno hasta el último producto.\n4. En E1 escribe 18% y, en la columna E, calcula el ITBIS de cada producto con =D2*$E$1.\n5. Cambia un precio y comprueba que los totales se actualizan solos.","materials":[{"id":"mat-img-itbis-factura-34","name":"Modelo de factura reactiva con Total e ITBIS del 18% ($F$1)","url":"/assets/images/excel_itbis_factura_1795447883578.jpg","type":"image","description":"Referencia visual del cálculo en cadena: cantidad × precio para obtener el subtotal de cada producto y multiplicación por la tasa fija del 18% para el ITBIS.","sizeByte":446648,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-3-5","title":"3.5 Operadores de Excel (aritméticos, comparación, concatenación, referencia)","durationMinutes":20,"summary":"Operadores Aritméticos, Comparación, Concatenación y de Referencia usados en fórmulas, con jerarquía y chuleta adaptada del contenido html original.","content":"### Operadores aritméticos\nToda fórmula comienza con el signo igual (`=`) para indicar a Excel que debe ejecutar un cálculo y no guardar texto.\n• **Suma (`+`)**: `=5+3` → `8`\n• **Resta (`-`)**: `=10-4` → `6`\n• **Multiplicación (`*`)**: `=6*7` → `42`\n• **División (`/`)**: `=20/4` → `5`\n• **Potencia (`^`)**: `=2^3` → `8`\n• **Porcentaje (`%`)**: `=25%` equivale a `0.25`\n\n### Operadores de comparación\nComparan dos valores y devuelven `VERDADERO` o `FALSO`. Son la base de funciones lógicas como `=SI()`.\n• `=` Igual (`=5=5` → `VERDADERO`)\n• `>` Mayor que / `<` Menor que\n• `>=` Mayor o igual / `<=` Menor o igual\n• `<>` Distinto de (`=5<>3` → `VERDADERO`)\n\n### Concatenación (`&`) y Referencia (`:`, `,`, `;`, `!`)\n• **Concatenación (`&`)**: Une textos o valores, por ejemplo `=\"Total: \"&100` → `\"Total: 100\"` o `=A1&\" \"&B1`.\n• **Rango (`:`)**: Define un bloque continuo (`=SUMA(A1:A5)`).\n• **Unión (`;` o `,`)**: Combina rangos separados (`=SUMA(A1:B2; C1:D2)`).\n• **Intersección (espacio)**: Celdas en común entre dos rangos (`=A1:C3 B2:D4` → `B2:C3`).\n• **Otra hoja (`!`)**: `=Hoja2!A1`.\n\n### Orden de evaluación (Jerarquía)\nExcel resuelve primero paréntesis `()`, luego potencias `^`, después multiplicación/división (`*`, `/`) y al final suma/resta (`+`, `-`). Ejemplo: `=(2+3)*4` da `20`, mientras que `=2+3*4` da `14`.\n\nDirígete a la pestaña **Prácticas** para resolver los ejercicios interactivos y descargar las hojas de trabajo.","materials":[{"id":"mat-img-tipos-operadores-35","name":"Operadores aritméticos, comparación y concatenación (&) con jerarquía","url":"/assets/images/excel_tipos_operadores_1795447919466.jpg","type":"image","description":"Tabla visual de prioridad de evaluación: 1) Paréntesis (), 2) Potencia ^, 3) Multiplicación/División (* /), 4) Suma/Resta (+ -), junto a concatenación (&) y comparadores.","sizeByte":459683,"uploadedAt":"2026-11-23T00:00:00.000Z"}]}]},{"id":"mod-excel-4","title":"MÓDULO 4 — FUNCIONES MATEMÁTICAS Y ESTADÍSTICAS BÁSICAS","durationMinutes":190,"quizQuestion":"¿Qué función suma celdas únicamente cuando cumplen múltiples condiciones simultáneas?","quizOptions":["SUMAR.SI.CONJUNTO","CONTAR.BLANCO","SUBTOTALES"],"quizCorrectIndex":0,"quizEnabled":true,"questions":[{"id":"q-m4-1","prompt":"¿Qué función suma celdas únicamente cuando cumplen múltiples condiciones simultáneas?","explanation":"SUMAR.SI.CONJUNTO (en inglés SUMIFS) permite especificar un rango de suma y múltiples pares de rango_criterio y criterio.","multiple":false,"options":[{"id":"q-m4-1-a","text":"SUMAR.SI.CONJUNTO"},{"id":"q-m4-1-b","text":"CONTAR.BLANCO"},{"id":"q-m4-1-c","text":"SUBTOTALES"},{"id":"q-m4-1-d","text":"PRODUCTO"}],"correctIndexes":[0]},{"id":"q-m4-2","prompt":"Verdadero o Falso: =REDONDEAR(15.678; 1) modifica el número almacenado redondeándolo a 15.7, mientras que ocultar decimales desde la pestaña Inicio solo cambia su vista.","explanation":"Verdadero. REDONDEAR altera el valor real utilizado en cálculos posteriores; los botones de decimales de la Cinta solo ajustan la presentación visual.","multiple":false,"options":[{"id":"q-m4-2-v","text":"Verdadero"},{"id":"q-m4-2-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m4-3","prompt":"Si A1:A5 contiene [10, \"Texto\", \"\", 25, \"Norte\"] (donde \"\" es vacía), ¿qué devuelve =CONTARA(A1:A5)?","explanation":"CONTARA cuenta todas las celdas que no están vacías (tanto números como textos): 10, \"Texto\", 25 y \"Norte\" = 4 celdas.","multiple":false,"options":[{"id":"q-m4-3-a","text":"2"},{"id":"q-m4-3-b","text":"4"},{"id":"q-m4-3-c","text":"1"},{"id":"q-m4-3-d","text":"5"}],"correctIndexes":[1]},{"id":"q-m4-4","prompt":"Selecciona TODAS las funciones que devuelven estadísticas ignorando filtros ocultos o respondiendo a condiciones:","explanation":"SUBTOTALES ignora filas ocultadas por AutoFiltro; PROMEDIO.SI promedia con condición; MAX.SI.CONJUNTO halla el máximo con criterios. CONTAR.BLANCO solo cuenta celdas vacías.","multiple":true,"options":[{"id":"q-m4-4-a","text":"SUBTOTALES(9; rango) suma solo las celdas visibles tras filtrar"},{"id":"q-m4-4-b","text":"PROMEDIO.SI calcula la media solo de filas que cumplen un criterio"},{"id":"q-m4-4-c","text":"MAX.SI.CONJUNTO encuentra el máximo filtrado por uno o más criterios"},{"id":"q-m4-4-d","text":"CONTAR.BLANCO suma las ventas visibles cuando aplicas AutoFiltro"}],"correctIndexes":[0,1,2]},{"id":"q-m4-5","prompt":"Verdadero o Falso: Para un conjunto de números [10, 10, 20, 40, 70], la MEDIANA es 20 y el PROMEDIO es 30.","explanation":"Verdadero. Al estar ordenados, el dato central es 20 (mediana), mientras que la suma 150 dividida entre 5 elementos da 30 (promedio).","multiple":false,"options":[{"id":"q-m4-5-v","text":"Verdadero"},{"id":"q-m4-5-f","text":"Falso"}],"correctIndexes":[0]},{"id":"q-m4-6","prompt":"¿Qué valor devuelve exactamente la fórmula =RESIDUO(17; 5)?","explanation":"Al dividir 17 entre 5, el cociente entero es 3 (3 × 5 = 15) y sobran 2 unidades como residuo o resto.","multiple":false,"options":[{"id":"q-m4-6-a","text":"3"},{"id":"q-m4-6-b","text":"2"},{"id":"q-m4-6-c","text":"3.4"},{"id":"q-m4-6-d","text":"5"}],"correctIndexes":[1]},{"id":"q-m4-7","prompt":"¿Qué argumento identifica a SUMA dentro de la función =SUBTOTALES(núm_función; rango)?","explanation":"En SUBTOTALES, el código 9 corresponde a SUMA (el 1 a PROMEDIO, el 2 a CONTAR, el 4 a MAX, etc.).","multiple":false,"options":[{"id":"q-m4-7-a","text":"9"},{"id":"q-m4-7-b","text":"1"},{"id":"q-m4-7-c","text":"4"},{"id":"q-m4-7-d","text":"0"}],"correctIndexes":[0]},{"id":"q-m4-8","prompt":"Verdadero o Falso: La función =ALEATORIO.ENTRE(1; 6) puede devolver números decimales como 3.45 cada vez que presionas F9.","explanation":"Falso. ALEATORIO.ENTRE devuelve exclusivamente números enteros dentro del intervalo especificado; quien genera decimales entre 0 y 1 es =ALEATORIO().","multiple":false,"options":[{"id":"q-m4-8-v","text":"Verdadero"},{"id":"q-m4-8-f","text":"Falso"}],"correctIndexes":[1]},{"id":"q-m4-9","prompt":"Si A1 contiene el puntaje 75, ¿qué devuelve =SI(A1>=70; \"Aprobado\"; \"Reprobado\")?","explanation":"Como 75 >= 70 es VERDADERO, la función toma el segundo argumento (\"Aprobado\").","multiple":false,"options":[{"id":"q-m4-9-a","text":"Reprobado"},{"id":"q-m4-9-b","text":"Aprobado"},{"id":"q-m4-9-c","text":"VERDADERO"},{"id":"q-m4-9-d","text":"#¡VALOR!"}],"correctIndexes":[1]},{"id":"q-m4-10","prompt":"Verdadero o Falso: La función =ABS(-45) devuelve 45 positivo porque calcula la magnitud absoluta sin signo negativo.","explanation":"Verdadero. ABS elimina el signo negativo y devuelve siempre el valor positivo de cualquier número.","multiple":false,"options":[{"id":"q-m4-10-v","text":"Verdadero"},{"id":"q-m4-10-f","text":"Falso"}],"correctIndexes":[0]}],"lessons":[{"id":"les-excel-4-1","title":"4.1 SUMA, RESTA y PRODUCTO — Excel Básico","durationMinutes":25,"summary":"Operaciones aritméticas con SUMA, RESTA (operador -) y PRODUCTO: ~10 ejercicios por función y explicaciones clave de que se suman las celdas.","content":"### 1. SUMA: `=SUMA(rango)`\nSuma todos los valores numéricos contenidos dentro del rango especificado. **Regla clave:** referencia siempre celdas (`=SUMA(A1:A4)`), nunca escribas números fijos dentro de la fórmula (`=SUMA(10+20)`), así Excel recalcula automáticamente si cambian los datos.\n• **Ejemplo:** Si `B2:B4` contiene `10`, `5` y `2`, `=SUMA(B2:B4)` devuelve `17`. También puedes sumar celdas no contiguas separando con `;`: `=SUMA(A1:A3; A5)`.\n\n### 2. RESTA con operador `-`\nEn Excel no existe una función `RESTA()`: se utiliza el operador aritmético `-` entre celdas.\n• **Ejemplo:** Con `A1 = 100` y `A2 = 37`, la fórmula `=A1-A2` devuelve `63`.\n\n### 3. PRODUCTO: `=PRODUCTO(rango)`\nMultiplica entre sí todos los números de un rango o lista de argumentos, ignorando textos o celdas vacías.\n• **Ejemplo:** Con `B2:B4` = `10`, `5` y `2`, `=PRODUCTO(B2:B4)` calcula `10 × 5 × 2 = 100`.\n\nPara poner en práctica estas tres operaciones, abre la pestaña **Prácticas** de esta lección.","materials":[{"id":"mat-img-suma-resta-producto-41","name":"Operaciones aritméticas en rango: =SUMA, Resta (-) y =PRODUCTO","url":"/assets/images/excel_suma_resta_producto_1795447920118.jpg","type":"image","description":"Comparación directa sobre la tabla B2:B4 (10, 5, 2): suma total con =SUMA(B2:B4) = 17, diferencia con =B2-B3 = 5 y multiplicación acumulada con =PRODUCTO(B2:B4) = 100.","sizeByte":348179,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-excel-basico-fichas-rapidas","name":"Fichas rápidas SUMA/RESTA/PRODUCTO/ANÁLITICAS","url":"/excel-basico/fichas-rapidas.txt","type":"doc","sizeByte":1033,"uploadedAt":"2026-11-22T00:00:00.000Z"}]},{"id":"les-excel-4-2","title":"4.2 REDONDEAR, REDONDEAR.MAS, REDONDEAR.MENOS","durationMinutes":15,"summary":"Redondeo preciso de decimales con =REDONDEAR, =REDONDEAR.MAS, =REDONDEAR.MENOS.","content":"### Control real del redondeo vs. formato visual\nReducir decimales desde la barra de herramientas solo cambia **cómo se ve** el número, pero conserva todos los decimales internos en los cálculos. Para modificar el **valor real almacenado**, usa funciones de redondeo (con `;` como separador de argumentos):\n\n• **`=REDONDEAR(número; núm_decimales)`**: Redondeo estándar al dígito más cercano (5 o más sube). Ejemplo: `=REDONDEAR(15.678; 1)` → `15.7`.\n• **`=REDONDEAR.MAS(número; núm_decimales)`**: Siempre redondea alejándose de cero (hacia arriba en positivos, hacia más negativo en negativos). Ejemplo: `=REDONDEAR.MAS(10.1; 0)` → `11`.\n• **`=REDONDEAR.MENOS(número; núm_decimales)`**: Siempre redondea acercándose a cero. Ejemplo: `=REDONDEAR.MENOS(10.9; 0)` → `10`.\n\nVisita la pestaña **Prácticas** para completar los ejercicios interactivos y descargar el libro de práctica.","materials":[{"id":"mat-img-redondeo-funciones-42","name":"Comparativa visual de funciones de redondeo y precisión decimal","url":"/assets/images/excel_redondeo_funciones_1795447920696.jpg","type":"image","description":"Efecto sobre un mismo número decimal (15.678): redondeo estándar (=REDONDEAR → 15.7), hacia arriba (=REDONDEAR.MAS → 16), corte sin redondear (=TRUNCAR → 15.6) y entero (=ENTERO → 15).","sizeByte":396883,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-3","title":"4.3 ENTERO, TRUNCAR, RESIDUO, POTENCIA, RAIZ, ABS","durationMinutes":20,"summary":"Funciones para extraer partes enteras, restos y potencias: =ENTERO, =TRUNCAR, =RESIDUO, =POTENCIA, =RAIZ, =ABS.","content":"### Extracción de enteros y restos\n• **`=ENTERO(número)`**: Redondea hacia abajo al entero inferior más cercano. En positivos quita decimales (`=ENTERO(2.7)` → `2`), pero en negativos baja un entero (`=ENTERO(-2.7)` → `-3`).\n• **`=TRUNCAR(número; [núm_decimales])`**: Corta los decimales sin redondear (`=TRUNCAR(-2.7)` → `-2`; `=TRUNCAR(15.678; 1)` → `15.6`).\n• **`=RESIDUO(número; divisor)`**: Devuelve únicamente el resto entero de una división (`=RESIDUO(10; 3)` → `1`). Muy útil para detectar números pares o múltiplos.\n\n### Potencias, raíces y magnitud\n• **`=POTENCIA(base; exponente)`**: Eleva una base a una potencia, equivalente al operador `^` (`=POTENCIA(5; 2)` → `25`).\n• **`=RAIZ(número)`**: Calcula la raíz cuadrada de un número positivo (`=RAIZ(25)` → `5`).\n• **`=ABS(número)`**: Devuelve el valor absoluto sin signo negativo (`=ABS(-45)` → `45`).\n\nPon a prueba cada función en la pestaña **Prácticas**.","materials":[{"id":"mat-img-matematicas-exactas-43","name":"Funciones matemáticas exactas: POTENCIA, RAIZ, RESIDUO y ABS","url":"/assets/images/excel_matematicas_exactas_1795447950908.jpg","type":"image","description":"Cuatro fichas técnicas visuales: elevación con =POTENCIA(5; 2) = 25, raíz cuadrada con =RAIZ(25) = 5, resto entero de división con =RESIDUO(10; 3) = 1 y magnitud positiva con =ABS(-45) = 45.","sizeByte":354588,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-4","title":"4.4 PROMEDIO, MEDIANA, MODA","durationMinutes":15,"summary":"Medidas de tendencia central: =PROMEDIO, =MEDIANA, =MODA.UNO.","content":"### Tres formas de resumir un conjunto de datos\nSobre un mismo rango numérico `A1:E1` con valores `10, 10, 20, 40, 70`, cada medida responde a una pregunta distinta:\n\n• **`=PROMEDIO(rango)`**: Suma todos los números y divide entre cuántos hay (`150 / 5 = 30`). Sensible a valores extremos muy altos o bajos.\n• **`=MEDIANA(rango)`**: Ordena los datos y toma exactamente el valor central (`20`). Si la cantidad es par, promedia los dos del medio.\n• **`=MODA.UNO(rango)`**: Identifica el valor que aparece con mayor frecuencia en el rango (`10`).\n\nPractica calculando estas medidas en la pestaña **Prácticas**.","materials":[{"id":"mat-img-tendencia-central-44","name":"Medidas de tendencia central: PROMEDIO, MEDIANA y MODA.UNO","url":"/assets/images/excel_tendencia_central_1795447950900.jpg","type":"image","description":"Sobre la serie ordenada A1:E1 (10, 10, 20, 40, 70): la media aritmética es 30, el valor central o mediana es 20 y el valor más repetido o moda es 10.","sizeByte":366240,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-5","title":"4.5 MAX, MIN, MAX.SI.CONJUNTO / MAXIFS, MIN.SI.CONJUNTO / MINIFS","durationMinutes":20,"summary":"Extremos globales y filtrados por criterios: =MAX/=MIN, =MAX.SI.CONJUNTO/=MAXIFS, =MIN.SI.CONJUNTO/=MINIFS.","content":"### Extremos globales: `MAX` y `MIN`\n• **`=MAX(rango)`**: Devuelve el valor numérico más grande del rango (`=MAX(5; 2; 9)` → `9`).\n• **`=MIN(rango)`**: Devuelve el valor numérico más pequeño del rango (`=MIN(5; 2; 9)` → `2`).\n\n### Extremos condicionales: `MAX.SI.CONJUNTO` / `MAXIFS` y `MIN.SI.CONJUNTO` / `MINIFS`\nEncuentran el máximo o mínimo únicamente entre las filas que cumplen uno o más criterios:\n• **Sintaxis:** `=MAX.SI.CONJUNTO(rango_máximo; rango_criterio1; criterio1; ...)` (o `=MAXIFS(...)` en Excel en inglés).\n• **Ejemplo:** Si `B1:B5` tiene montos y `A1:A5` tiene categorías, `=MAX.SI.CONJUNTO(B1:B5; A1:A5; \"Venta\")` devuelve el monto más alto únicamente dentro de `\"Venta\"`.\n• Para el menor condicional se sigue exactamente el mismo orden con `=MIN.SI.CONJUNTO(...)` / `=MINIFS(...)`.\n\nCompleta los 15 ejercicios correspondientes en la pestaña **Prácticas**.","materials":[{"id":"mat-img-max-min-ifs-45","name":"Extremos globales y condicionales: MAX, MIN, K.ESIMO y MAX.SI.CONJUNTO","url":"/assets/images/excel_max_min_ifs_1795447951483.jpg","type":"image","description":"Contraste sobre ventas por sucursal: máximo global (450), mínimo global (100), segundo mayor (=K.ESIMO.MAYOR = 300) y máximo filtrado por sucursal Norte (=MAX.SI.CONJUNTO = 300).","sizeByte":428681,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-6","title":"4.6 CONTAR, CONTARA, CONTAR.BLANCO","durationMinutes":15,"summary":"Conteo de celdas numéricas, no vacías y espacios en blanco.","content":"### Cómo cuenta Excel según el tipo de contenido\nNo todas las funciones de conteo cuentan lo mismo. Sobre un rango `A1:A5` con dos números, dos textos y una celda realmente vacía:\n\n• **`=CONTAR(rango)`**: Cuenta únicamente celdas con **números o fechas** (resultado: `2`). Ignora textos y celdas vacías.\n• **`=CONTARA(rango)`**: Cuenta **cualquier celda no vacía**, incluyendo texto, números, fechas, errores o fórmulas que devuelven `\"\"` (resultado: `4`).\n• **`=CONTAR.BLANCO(rango)`**: Cuenta exclusivamente **celdas vacías** (resultado: `1`).\n\nRealiza las prácticas interactivas de conteo en la pestaña **Prácticas**.","materials":[{"id":"mat-img-conteo-basico-46","name":"Diferencia visual entre CONTAR, CONTARA y CONTAR.BLANCO","url":"/assets/images/excel_conteo_basico_1795447884246.jpg","type":"image","description":"Sobre la columna A1:A5 con dos números, dos textos y una celda vacía: =CONTAR devuelve 2 (solo números), =CONTARA devuelve 4 (todas las ocupadas) y =CONTAR.BLANCO devuelve 1.","sizeByte":441130,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-7","title":"4.7 CONTAR.SI, CONTAR.SI.CONJUNTO","durationMinutes":20,"summary":"Conteo condicional simple y multicriterio con ;, comodines * y ?.","content":"### Conteo con una condición: `=CONTAR.SI(rango; criterio)`\nCuenta cuántas celdas dentro de un rango cumplen una condición específica. Los criterios de texto o comparación (`\">=20\"`, `\"Norte\"`) siempre van entre comillas:\n• **Ejemplo numérico:** `=CONTAR.SI(A1:A5; \">=20\")` cuenta las celdas con valor mayor o igual a 20.\n• **Comodines de texto:** Usa `*` para cualquier cantidad de caracteres (`\"R*\"` coincide con todo texto que empiece con R) y `?` para un solo carácter.\n\n### Conteo con múltiples condiciones: `=CONTAR.SI.CONJUNTO(rango1; criterio1; rango2; criterio2; ...)`\nCuenta únicamente las filas que cumplen **todos los criterios simultáneamente** (lógica **Y**). Cada rango debe tener exactamente el mismo número de filas.\n• **Ejemplo:** `=CONTAR.SI.CONJUNTO(A2:A10; \"Norte\"; B2:B10; \"Activo\")` cuenta solo los registros que son de la zona Norte y además están Activos.\n\nPon a prueba ambos casos en la pestaña **Prácticas**.","materials":[{"id":"mat-img-contar-si-47","name":"Conteo condicional simple y multicriterio: CONTAR.SI y CONTAR.SI.CONJUNTO","url":"/assets/images/excel_contar_si_1795447885491.jpg","type":"image","description":"Muestra cómo =CONTAR.SI cuenta las filas que cumplen 1 criterio (Área=\"Norte\" → 3) y =CONTAR.SI.CONJUNTO exige simultáneamente varios criterios (Norte + Activo → 2).","sizeByte":427872,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-8","materials":[{"id":"mat-img-sumar-si-48","name":"Suma condicional: =SUMAR.SI y =SUMAR.SI.CONJUNTO","url":"/assets/images/excel_sumar_si_1795447949802.jpg","type":"image","description":"Filtrado de sumas sobre tabla Área/Venta: =SUMAR.SI(A2:A5; \"Norte\"; B2:B5) suma únicamente las filas de Norte (100 + 200 = 300), extensible a múltiples condiciones con .CONJUNTO.","sizeByte":427266,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-excel-basico-fichas-rapidas","name":"Fichas rápidas SUMA/RESTA/PRODUCTO/ANÁLITICAS","url":"/excel-basico/fichas-rapidas.txt","type":"doc","sizeByte":1033,"uploadedAt":"2026-11-22T00:00:00.000Z"}],"title":"4.8 SUMAR.SI, SUMAR.SI.CONJUNTO","durationMinutes":20,"summary":"Suma segmentada con criterios; usa ; en Excel Básico.","content":"### 1. Suma con un criterio: `=SUMAR.SI(rango_criterio; criterio; [rango_suma])`\nSuma valores únicamente de las filas que cumplen la condición indicada:\n• **`rango_criterio`**: Columna donde Excel evalúa la condición (ej. `A2:A5` con áreas).\n• **`criterio`**: Condición entre comillas si es texto u operador (`\"Norte\"`, `\">100\"`, `\"Rar*\"`).\n• **`[rango_suma]`**: Columna con los números a sumar (ej. `B2:B5`). Si se omite, suma el mismo `rango_criterio`.\n• **Ejemplo:** `=SUMAR.SI(A2:A5; \"Norte\"; B2:B5)` suma solo los montos de la fila donde aparece `\"Norte\"`.\n\n### 2. Suma con múltiples criterios: `=SUMAR.SI.CONJUNTO(rango_suma; rango_criterio1; criterio1; ...)`\n**¡Cuidado con el orden de los argumentos!** A diferencia de `SUMAR.SI`, aquí el **rango que se va a sumar va primero**, seguido de los pares de rango y criterio.\n• **Ejemplo:** `=SUMAR.SI.CONJUNTO(C2:C10; A2:A10; \"Norte\"; B2:B10; \"Pagado\")` suma la columna `C` solo cuando el área es `\"Norte\"` y el estado es `\"Pagado\"`.\n\nResuelve los 15 ejercicios paso a paso y descarga las plantillas en la pestaña **Prácticas**."},{"id":"les-excel-4-9","materials":[{"id":"mat-img-promedio-si-49","name":"Promedio condicional con =PROMEDIO.SI y =PROMEDIO.SI.CONJUNTO","url":"/assets/images/excel_promedio_si_1795447883774.jpg","type":"image","description":"Calcula el promedio únicamente de las filas coincidentes: =PROMEDIO.SI(A2:A5; \"Ventas\"; B2:B5) promedia 100 y 80 entre 2 elementos devolviendo 90.","sizeByte":378859,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-excel-basico-fichas-rapidas","name":"Fichas rápidas SUMA/RESTA/PRODUCTO/ANÁLITICAS","url":"/excel-basico/fichas-rapidas.txt","type":"doc","sizeByte":1033,"uploadedAt":"2026-11-22T00:00:00.000Z"}],"title":"4.9 PROMEDIO.SI, PROMEDIO.SI.CONJUNTO","durationMinutes":15,"summary":"Promedios segmentados con =PROMEDIO.SI y =PROMEDIO.SI.CONJUNTO.","content":"### 1. Promedio con una condición: `=PROMEDIO.SI(rango_criterio; criterio; [rango_promedio])`\nCalcula la media aritmética únicamente de las celdas que cumplen el criterio indicado (ignorando las demás filas y evitando dividir entre el total de la tabla).\n• **Ejemplo:** Si en `A2:A5` hay departamentos y en `B2:B5` ventas (`100` y `80` para `\"Ventas\"`), `=PROMEDIO.SI(A2:A5; \"Ventas\"; B2:B5)` calcula `(100 + 80) / 2 = 90`.\n\n### 2. Promedio multicriterio: `=PROMEDIO.SI.CONJUNTO(rango_promedio; rango_criterio1; criterio1; ...)`\nAl igual que `SUMAR.SI.CONJUNTO`, coloca primero el rango numérico a promediar y después los pares de `rango_criterio; criterio`.\n• **Nota:** Si ninguna fila cumple todas las condiciones, devuelve `#¡DIV/0!` (puedes envolverla con `=SI.ERROR(...)` cuando sea necesario).\n\nPractica esta función en la pestaña **Prácticas**."},{"id":"les-excel-4-10","title":"4.10 SUBTOTALES (con filtros)","durationMinutes":15,"summary":"Agregaciones dinámicas respetando filtros AutoFiltro (SUBTOTAL / SUBTOTALES).","content":"### ¿Por qué usar `=SUBTOTALES(...)` en lugar de `=SUMA(...)`?\nCuando activas un **AutoFiltro** en una tabla, `=SUMA(A2:A20)` sigue sumando las filas que quedaron ocultas por el filtro. En cambio, **`=SUBTOTALES(núm_función; ref1)`** calcula únicamente sobre las **filas visibles**.\n\n### Códigos de función más utilizados\n• **`1`**: `PROMEDIO`\n• **`2`**: `CONTAR`\n• **`3`**: `CONTARA`\n• **`4`** / **`5`**: `MAX` / `MIN`\n• **`9`**: `SUMA` (el más común: `=SUBTOTALES(9; B2:B50)`)\n\nPonlo a prueba con tablas filtradas en la pestaña **Prácticas**.","materials":[{"id":"mat-img-subtotales-filtro-410","name":"Comparación SUMA vs =SUBTOTALES(9; ...) con AutoFiltro activo","url":"/assets/images/excel_subtotales_filtro_1795447884019.jpg","type":"image","description":"Demuestra por qué =SUMA sigue sumando filas ocultas al filtrar (200), mientras que =SUBTOTALES(9; rango) suma exclusivamente las filas visibles (150).","sizeByte":368400,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-11","title":"4.11 ALEATORIO, ALEATORIO.ENTRE","durationMinutes":10,"summary":"Generación de números aleatorios y enteros en intervalo.","content":"### Generación de valores dinámicos\n• **`=ALEATORIO()`**: No lleva argumentos. Genera un número decimal uniforme mayor o igual a `0` y menor que `1` (ej. `0.4829`).\n• **`=ALEATORIO.ENTRE(inferior; superior)`**: Devuelve un número entero aleatorio dentro del intervalo cerrado especificado (por ejemplo, `=ALEATORIO.ENTRE(1; 6)` simula el lanzamiento de un dado).\n\n### Comportamiento de recálculo\nSon funciones **volátiles**: cada vez que editas cualquier celda o pulsas la tecla `F9`, generan nuevos valores automáticamente. Si deseas fijar los números generados para que no cambien más, copia las celdas y usa **Pegado especial → Valores**.\n\nExplora los ejercicios en la pestaña **Prácticas**.","materials":[{"id":"mat-img-aleatorio-funciones-411","name":"Generación aleatoria con =ALEATORIO() y =ALEATORIO.ENTRE()","url":"/assets/images/excel_aleatorio_funciones_1795447952500.jpg","type":"image","description":"Diferencia entre decimales uniformes entre 0 y 1 (=ALEATORIO()) y números enteros acotados en un rango (=ALEATORIO.ENTRE(10; 50)), recalculados automáticamente con F9.","sizeByte":352640,"uploadedAt":"2026-11-23T00:00:00.000Z"}]},{"id":"les-excel-4-12","materials":[{"id":"mat-img-funcion-si-412","name":"Diagrama de flujo: Toma de decisiones con =SI(prueba_lógica; verdadero; falso)","url":"/assets/images/excel_funcion_si_flujo_1795445065167.jpg","type":"image","description":"Árbol lógico de bifurcación: evalúa la condición booleana del primer argumento y devuelve la rama Verdadero (segundo argumento) o Falso (tercer argumento).","sizeByte":401570,"uploadedAt":"2026-11-23T00:00:00.000Z"},{"id":"mat-excel-basico-fichas-rapidas","name":"Fichas rápidas SUMA/RESTA/PRODUCTO/ANÁLITICAS","url":"/excel-basico/fichas-rapidas.txt","type":"doc","sizeByte":1033,"uploadedAt":"2026-11-22T00:00:00.000Z"}],"title":"4.12 SI (Función lógica de decisión)","durationMinutes":15,"summary":"SI(prueba_lógica; valor_si_verdadero; valor_si_falso), anidación y Y/O.","content":"### Estructura de la decisión lógica: `=SI(prueba_lógica; valor_si_verdadero; [valor_si_falso])`\nEvalúa una condición (`A1>=60`) y toma uno de dos caminos posibles:\n• **`prueba_lógica`**: Expresión que devuelve `VERDADERO` o `FALSO` (ej. `A1>=60`, `B1=\"Pagado\"`).\n• **`valor_si_verdadero`**: Resultado devuelto cuando la condición se cumple (ej. `\"Aprobado\"` o una fórmula como `B1*0.10`).\n• **`[valor_si_falso]`**: Resultado devuelto cuando la condición no se cumple (ej. `\"Reprobado\"`).\n\n### Combinaciones clave: `SI` anidado, `Y()` y `O()`\n• **Anidación:** Coloca otro `SI()` en el tercer argumento para evaluar múltiples escalas: `=SI(A1>=90; \"Excelente\"; SI(A1>=70; \"Aprobado\"; \"Reprobado\"))`.\n• **`Y(cond1; cond2)`**: Exige que **todas** las condiciones sean verdaderas (`=SI(Y(A1>=85; B1=\"Activo\"); \"Bono\"; \"Sin bono\")`).\n• **`O(cond1; cond2)`**: Basta con que **al menos una** condición sea verdadera.\n\nPractica casos reales de evaluación y reglas de negocio en la pestaña **Prácticas**."}]}]'::jsonb, NULL, NULL);
COMMIT;
